-static const int type[VME_DEVS] = {	MASTER_MINOR,	MASTER_MINOR,
-					MASTER_MINOR,	MASTER_MINOR,
-					SLAVE_MINOR,	SLAVE_MINOR,
-					SLAVE_MINOR,	SLAVE_MINOR,
-					CONTROL_MINOR
-				};
