-static ssize_t resource_to_user(int minor, char __user *buf, size_t count,
-				loff_t *ppos)
-{
-	ssize_t copied = 0;
-
-	if (count > image[minor].size_buf)
-		count = image[minor].size_buf;
-
-	copied = vme_master_read(image[minor].resource, image[minor].kern_buf,
-				 count, *ppos);
-	if (copied < 0)
-		return (int)copied;
-
-	if (copy_to_user(buf, image[minor].kern_buf, (unsigned long)copied))
-		return -EFAULT;
-
-	return copied;
-}
-
-static ssize_t resource_from_user(unsigned int minor, const char __user *buf,
-				  size_t count, loff_t *ppos)
-{
-	if (count > image[minor].size_buf)
-		count = image[minor].size_buf;
-
-	if (copy_from_user(image[minor].kern_buf, buf, (unsigned long)count))
-		return -EFAULT;
-
-	return vme_master_write(image[minor].resource, image[minor].kern_buf,
-				count, *ppos);
-}
-
-static ssize_t buffer_to_user(unsigned int minor, char __user *buf,
-			      size_t count, loff_t *ppos)
-{
-	void *image_ptr;
-
-	image_ptr = image[minor].kern_buf + *ppos;
-	if (copy_to_user(buf, image_ptr, (unsigned long)count))
-		return -EFAULT;
-
-	return count;
-}
-
-static ssize_t buffer_from_user(unsigned int minor, const char __user *buf,
-				size_t count, loff_t *ppos)
-{
-	void *image_ptr;
-
-	image_ptr = image[minor].kern_buf + *ppos;
-	if (copy_from_user(image_ptr, buf, (unsigned long)count))
-		return -EFAULT;
-
-	return count;
-}
-
-static ssize_t vme_user_read(struct file *file, char __user *buf, size_t count,
-			     loff_t *ppos)
-{
-	unsigned int minor = iminor(file_inode(file));
-	ssize_t retval;
-	size_t image_size;
-
-	if (minor == CONTROL_MINOR)
-		return 0;
-
-	mutex_lock(&image[minor].mutex);
-
-	/* XXX Do we *really* want this helper - we can use vme_*_get ? */
-	image_size = vme_get_size(image[minor].resource);
-
-	/* Ensure we are starting at a valid location */
-	if ((*ppos < 0) || (*ppos > (image_size - 1))) {
-		mutex_unlock(&image[minor].mutex);
-		return 0;
-	}
-
-	/* Ensure not reading past end of the image */
-	if (*ppos + count > image_size)
-		count = image_size - *ppos;
-
-	switch (type[minor]) {
-	case MASTER_MINOR:
-		retval = resource_to_user(minor, buf, count, ppos);
-		break;
-	case SLAVE_MINOR:
-		retval = buffer_to_user(minor, buf, count, ppos);
-		break;
-	default:
-		retval = -EINVAL;
-	}
-
-	mutex_unlock(&image[minor].mutex);
-	if (retval > 0)
-		*ppos += retval;
-
-	return retval;
-}
-
-static ssize_t vme_user_write(struct file *file, const char __user *buf,
-			      size_t count, loff_t *ppos)
-{
-	unsigned int minor = iminor(file_inode(file));
-	ssize_t retval;
-	size_t image_size;
-
-	if (minor == CONTROL_MINOR)
-		return 0;
-
-	mutex_lock(&image[minor].mutex);
-
-	image_size = vme_get_size(image[minor].resource);
-
-	/* Ensure we are starting at a valid location */
-	if ((*ppos < 0) || (*ppos > (image_size - 1))) {
-		mutex_unlock(&image[minor].mutex);
-		return 0;
-	}
-
-	/* Ensure not reading past end of the image */
-	if (*ppos + count > image_size)
-		count = image_size - *ppos;
-
-	switch (type[minor]) {
-	case MASTER_MINOR:
-		retval = resource_from_user(minor, buf, count, ppos);
-		break;
-	case SLAVE_MINOR:
-		retval = buffer_from_user(minor, buf, count, ppos);
-		break;
-	default:
-		retval = -EINVAL;
-	}
-
-	mutex_unlock(&image[minor].mutex);
-
-	if (retval > 0)
-		*ppos += retval;
-
-	return retval;
-}
-
-static loff_t vme_user_llseek(struct file *file, loff_t off, int whence)
-{
-	unsigned int minor = iminor(file_inode(file));
-	size_t image_size;
-	loff_t res;
-
-	switch (type[minor]) {
-	case MASTER_MINOR:
-	case SLAVE_MINOR:
-		mutex_lock(&image[minor].mutex);
-		image_size = vme_get_size(image[minor].resource);
-		res = fixed_size_llseek(file, off, whence, image_size);
-		mutex_unlock(&image[minor].mutex);
-		return res;
-	}
-
-	return -EINVAL;
-}
