-			}
-
-			return vme_irq_generate(vme_user_bridge,
-						  irq_req.level,
-						  irq_req.statid);
-		}
-		break;
-	case MASTER_MINOR:
-		switch (cmd) {
-		case VME_GET_MASTER:
-			memset(&master, 0, sizeof(master));
-
-			/* XXX	We do not want to push aspace, cycle and width
-			 *	to userspace as they are
-			 */
-			retval = vme_master_get(image[minor].resource,
-						&master.enable,
-						&master.vme_addr,
-						&master.size, &master.aspace,
-						&master.cycle, &master.dwidth);
-
-			copied = copy_to_user(argp, &master,
-					      sizeof(master));
-			if (copied) {
-				pr_warn("Partial copy to userspace\n");
-				return -EFAULT;
-			}
-
-			return retval;
-
-		case VME_SET_MASTER:
-
-			if (image[minor].mmap_count != 0) {
-				pr_warn("Can't adjust mapped window\n");
-				return -EPERM;
-			}
-
-			copied = copy_from_user(&master, argp, sizeof(master));
-			if (copied) {
-				pr_warn("Partial copy from userspace\n");
-				return -EFAULT;
-			}
-
-			/* XXX	We do not want to push aspace, cycle and width
-			 *	to userspace as they are
-			 */
-			return vme_master_set(image[minor].resource,
-				master.enable, master.vme_addr, master.size,
-				master.aspace, master.cycle, master.dwidth);
-
-			break;
-		}
-		break;
-	case SLAVE_MINOR:
-		switch (cmd) {
-		case VME_GET_SLAVE:
-			memset(&slave, 0, sizeof(slave));
-
-			/* XXX	We do not want to push aspace, cycle and width
-			 *	to userspace as they are
-			 */
-			retval = vme_slave_get(image[minor].resource,
-					       &slave.enable, &slave.vme_addr,
-					       &slave.size, &pci_addr,
-					       &slave.aspace, &slave.cycle);
-
-			copied = copy_to_user(argp, &slave,
-					      sizeof(slave));
-			if (copied) {
-				pr_warn("Partial copy to userspace\n");
-				return -EFAULT;
-			}
-
-			return retval;
-
