 	int ret;
 
@@ -1242,29 +1274,10 @@ int cs35l41_probe(struct cs35l41_private *cs35l41, const struct cs35l41_hw_cfg *
 			goto err;
 		}
 	}
-	if (cs35l41->reset_gpio) {
-		/* satisfy minimum reset pulse width spec */
