+struct ad4691_state {
+	const struct ad4691_chip_info *info;
+	struct regmap *regmap;
+	struct spi_device *spi;
+
+	int vref_uV;
+
+	bool refbuf_en;
+	bool ldo_en;
+	/*
+	 * Synchronize access to members of the driver state, and ensure
+	 * atomicity of consecutive SPI operations.
